import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def transform(g):
    H,W=len(g),len(g[0])
    fives=[(i,j) for i in range(H) for j in range(W) if g[i][j]==5]
    # object cells: non-zero, non-5
    obj=[(i,j,g[i][j]) for i in range(H) for j in range(W) if g[i][j] not in (0,5)]
    out=[row[:] for row in g]
    for i,j in fives: out[i][j]=0
    if len(fives)==2:
        (r1,c1),(r2,c2)=fives
        for dr,dc in ((r2-r1,c2-c1),(r1-r2,c1-c2)):
            if all(0<=i+dr<H and 0<=j+dc<W for i,j,_ in obj):
                for i,j,v in obj: out[i+dr][j+dc]=v
                break
    return out

for k in ['Demo pair 1 input','Demo pair 2 input']:
    print(k, transform(G[k])==G[k.replace('input','output')])
print(json.dumps(transform(G['Test input'])))
